// Helper functions
export function getNounsByCategory(category: string): Word[] {
  return nouns.filter(noun => noun.category === category);
}

export function getCategories(): string[] {
  return [...new Set(nouns.map(noun => noun.category))];
}

export function searchNouns(query: string): Word[] {
  const lowerQuery = query.toLowerCase();
  return nouns.filter(
    noun =>
      noun.spanish.toLowerCase().includes(lowerQuery) ||
      noun.english.toLowerCase().includes(lowerQuery)
  );
}

export function getNounById(id: string): Word | undefined {
  return nouns.find(noun => noun.id === id);
}

export function getRandomNouns(count: number): Word[] {
  const shuffled = [...nouns].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}
